/**It is very important that the class name is added to the section as some sites us this to modify its last children in the blocks array (like removing margins etc) */
export const HasCorrectSectionClassName: Story = {
  args: {
    sectionClassName: "my-custom-class-for-section",
    contentfulId: "my-custom-contentful-id",
    mode: defaultMode,
    children: (
      <>
        <style>
          {`
          .my-custom-class-for-section p {
            text-decoration: underline;
          }
        `}
        </style>
        <p>I should have an underline</p>
      </>
    ),
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const section = canvas.getByTestId("my-custom-contentful-id");
    expect(section.className).toContain("my-custom-class-for-section");

    const paragraph = canvas.getByText("I should have an underline");
    const computedStyle = getComputedStyle(paragraph);
    expect(computedStyle.textDecoration).toContain("underline");
  },
};

export const DarkMode: Story = {
  args: {
    contentfulId: "my-custom-contentful-id",
    backgroundColor: "#00311e", //Dark green from the Kolmården color palette
    mode: {
      currentMode: "DARK", //Say that this is a dark mode background wrapper
      classNames: {
        DARK: "kolmarden-primary-dark",
        LIGHT: "kolmarden-secondary",
      },
    },
    children: <TextBlock title="This is a title" />,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    //Assert that the section has the correct class name
    const section = canvas.getByTestId("my-custom-contentful-id");
    expect(section.className).toContain("kolmarden-primary-dark");
    expect(section.className).not.toContain("kolmarden-secondary");

    //Assert that the title gets the color of kolmarde-primary-dark-600 which is #00ba7e or rgb(0,186,126)
    const title = canvas.getByText("This is a title");
    const computedStyle = getComputedStyle(title);
    expect(computedStyle.color).toBe("rgb(0, 186, 126)");
  },
};
