import { PropsWithChildren } from "react";
import styles from "./background-wrapper-block.module.less";

type Props = {
  /** The contentful id of the block (useful for our Chrome plugins)*/
  contentfulId: string;
  /** The `mode.className` are the mandatory classNames that will be added to thematize the content in the background either `LIGHT` or `DARK`.
   * The `mode.currentMode` is the current mode (`LIGHT` or `DARK`) of this background. This is optional, but when used the className of the corresponding mode will be applied.
   *
   * For example this
   * ```js
   * {
   * currentMode: "DARK",
   *  classNames: {
   *    LIGHT: 'furuvik-primary-light',
   *    DARK: 'furuvik-primary-dark'
   *   }
   * }
   * ```
   *
   * would add the `furuvik-primary-dark` className on the section since the currentMode is `DARK`.
   *
   * (the `classNames` attribute is probably hard coded in the site, while the `currentMode` is different for different backgrounds in Contentful)
   */
  mode: {
    currentMode?: "LIGHT" | "DARK";
    classNames: {
      LIGHT: string;
      DARK: string;
    };
  };
  /** The images to render. The browser will itself decide when it should fetch the high vs low quality images using the image-set() function */
  imageUrls?: {
    default: string;
    highQuality: string;
    lowQuality: string;
  };
  /** If set without imageUrls, the background color will be displayed as the full background.
   * If set _with_ imageUrls and the images have transparent channels, the color will show through the images */
  backgroundColor?: string;
  /** Used to  give the image an opacity level*/
  opacity?: number;
  /**  Used to set background-size:cover on the image instead of repeating it */
  backgroundAsCover?: boolean;
  /** An SVG-pattern that will sit on top of the background wrapper and get the same color as the `backgroundColor` prop */
  topPattern?: string;
  /** Useful for adding a className to the section that might be used on the sites for e.g. having CSS selector and modify the first/last block in the background */
  sectionClassName?: string;
};

const BackgroundWrapperBlock = ({
  contentfulId,
  mode,
  imageUrls,
  backgroundColor,
  opacity,
  backgroundAsCover,
  topPattern,
  sectionClassName = "",
  children,
}: PropsWithChildren<Props>) => {
  const cssVariables = {
    "--background-color": backgroundColor,
    "--image-url-default": imageUrls?.default && `url(${imageUrls?.default})`,
    "--image-url-high-quality": imageUrls?.highQuality && `url(${imageUrls?.highQuality})`,
    "--image-url-low-quality": imageUrls?.lowQuality && `url(${imageUrls?.lowQuality})`,
    "--opacity": opacity,
  } as React.CSSProperties;

  const hasImage = !!imageUrls;
  const modeClassName = mode.currentMode ? mode.classNames[mode.currentMode] : "";

  return (
    <section
      data-testid={contentfulId}
      data-contentful-id={contentfulId}
      className={`${styles.section} ${sectionClassName} ${modeClassName}`}
      style={cssVariables}
    >
      {topPattern && (
        <div className={styles.breakingPatternWrapper}>
          <svg
            x="0px"
            y="0px"
            viewBox="0 0 900 43"
            version="1.1"
            xmlns="http://www.w3.org/2000/svg"
            xmlnsXlink="http://www.w3.org/1999/xlink"
          >
            <path className={styles.path} fillOpacity="0.0" d={topPattern} fillRule="nonzero"></path>
          </svg>
        </div>
      )}
      <div className={styles.outer}>
        <div className={styles.inner} data-background-as-cover={!!backgroundAsCover} data-has-image={hasImage}></div>
      </div>
      {children}
    </section>
  );
};

export default BackgroundWrapperBlock;

/** Exporting this live preview-config object since it will probably be the same across sites. */
export const backgroundWrapperBlockLivePreviewConfig = {
  aliases: [{ original: "backgroundColor", alias: "backgroundColorHex" }],
  gatsbyImage: [
    {
      nameInContentful: "backgroundPattern",
      targetPaths: ["highQuality", "lowQuality"],
    },
  ],
  nestedFields: ["topPattern"],
};
